  str_help_uiaircraftmazeroom_details2 = "1. การสำรวจสามารถเพิ่มจำนวนชิ้นส่วนจารึกที่ได้รับจากดินแดนลับได้\n2. การอัปเกรดห้องนี้จะปลดล็อกด่านดินแดนลับเพิ่มเติม ซึ่งสามารถเคลียร์เพื่อรับรางวัลที่ดีกว่าเดิม",
  str_help_uiaircraftresourceroom_explain = "ข้อมูลสถานีทรัพยากรโคลอสซัส",
