  str_help_uiaircraftresourceroom_title2 = "ข้อมูลการฟื้นฟูแคริเออร์:",
  str_help_uiaircraftresourceroom_details1 = "1. ปลดล็อกดันเจี้ยนชิงทรัพยากรเพิ่ม\n2. ฟื้นฟูแคริเออร์\n3. เก็บแคริเออร์\n4. การอัปเกรดห้องหรือจัดวางออโรเรียนสามารถเพิ่มความเร็วการฟื้นฟูของแคริเออร์ได้",
  str_help_uiaircraftresourceroom_details2 = "เมื่อแคริเออร์ฟื้นฟูถึงขีดจำกัดการเก็บสูงสุดแล้ว จะไม่สามารถฟื้นฟูได้อีก",
  str_help_uiaircraftprismroom_explain = "ข้อมูลเสาปริซึมโคลอสซัส",
  str_help_uiaircraftprismroom_title1 = "ข้อมูลเสาปริซึม:",
  str_help_uiaircraftprismroom_details1 = "1. เสาปริซึมจะสร้างปริซึมโดยอัตโนมัติ\n2. เสาปริซึมสามารถเก็บปริซึมได้เช่นกัน\n3. เสาปริซึมเลเวลสูง ๆ จะช่วยเพิ่มความจุปริซึมสูงสุดของคุณ\n4. การอัปเกรดห้องนี้และจัดวางออโรเรียนสามารถเพิ่มความเร็วการสร้างปริซึมได้",
