  str_help_uidrawcardcontroller_title4 = "ข้อมูลตัวอย่างออโรเรียน:",
  str_help_uidrawcardcontroller_title5 = "ข้อมูลการอัญเชิญหมุนเวียน:",
  str_help_uidrawcardcontroller_details1 = "ในอีเวนต์อัญเชิญสำหรับมือใหม่จะใช้เพียงลูมแอมเบอร์เท่านั้น",
  str_help_uidrawcardcontroller_details2 = "1. การอัญเชิญจำกัดเวลาจะต้องใช้สตาร์แฟลร์พิเศษ\n2. ถ้าคุณมีสตาร์แฟลร์พิเศษไม่เพียงพอ สามารถใช้ลูมแอมเบอร์เพื่อรับเพิ่มได้",
  str_help_uidrawcardcontroller_details3 = "1. การอัญเชิญตัวหลักจะต้องใช้สตาร์แฟลร์\n2. ถ้าคุณมีสตาร์แฟลร์ไม่เพียงพอ สามารถใช้ลูมแอมเบอร์เพื่อรับเพิ่มได้",
  str_help_uidrawcardcontroller_details4 = "คุณสามารถดูค่าสถานะและสกิลของออโรเรียนเมื่อเลื่อนขั้นถึงสูงสุด โดยกดที่รูปประจำตัวของออโรเรียนหรือแถบรายชื่อออโรเรียน",
  str_help_uidrawcardcontroller_details5 = "1. การอัญเชิญแบบหมุนต้องใช้สตาร์แฟลร์\n2. ถ้าคุณมีสตาร์แฟลร์ไม่เพียงพอ สามารถใช้ลูมแอมเบอร์เพื่อรับเพิ่มได้",
  str_help_helppet_title1 = "ข้อมูลแนะนำการสนับสนุน",
  str_help_helppet_details1 = "1. คุณสามารถกำหนดออโรเรียนสนับสนุน 1 รายสำหรับธาตุแต่ละอย่างได้ สูงสุด 4 ออโรเรียน\n2. เพื่อนของคุณสามารถอัญเชิญออโรเรียนสนับสนุนไปชั่วคราวได้ แต่คุณก็ยังสามารถจัดวางพวกเขาในการต่อสู้ของคุณได้",
  str_help_helppet_title2 = "ออโรเรียนสนับสนุน",
  str_help_helppet_details2 = "1. คุณสามารถอัญเชิญออโรเรียนสนับสนุนของเพื่อนมาชั่วคราว หรือจะใช้ออโรเรียนสนับสนุนที่เกมจัดหาให้แบบสุ่มเพื่อช่วยในการต่อสู้ก็ได้\n2. หลังจากจัดวางออโรเรียนสนับสนุนในขบวนทัพแล้ว พวกเขาจะสู้เพื่อคุณเหมือนเป็นออโรเรียนของคุณเอง",
  str_help_helppet_title3 = "ข้อจำกัดของออโรเรียนสนับสนุน",
  str_help_helppet_details3 = "1. ออโรเรียนสายสนับสนุนสามารถจัดวางได้วันละหนึ่งครั้งเท่านั้น แต่ไม่จำกัดจำนวนออโรเรียนต่าง ๆ ที่สามารถจัดวางได้\n2. จำนวนครั้งจะหายไปเมื่อเคลียร์ด่านแล้วเท่านั้น การแพ้หรือออกจะไม่นับจำนวนครั้ง",
  str_help_petequip_title1 = "ข้อมูลอุปกรณ์ออโรเรียน",
  str_help_petequip_details1 = "1. เมื่อออโรเรียนถึงขั้น I แล้ว อุปกรณ์ออโรเรียนจะปลดล็อก\n2. อุปกรณ์ออโรเรียนสามารถเพิ่ม ATK, DEF, HP ของออโรเรียนและดาเมจชนะทางธาตุได้\n3. หลังจากปลดล็อกอุปกรณ์ ออโรเรียนจะได้รับสกิลอุปกรณ์ การอัปเกรดอุปกรณ์จะเพิ่มเอฟเฟกต์ของสกิลอุปกรณ์",
  str_help_petequip_title2 = "ดาเมจชนะทางธาตุ",
  str_help_petequip_details2 = "1. ดาเมจชนะทางธาตุพื้นฐานของออโรเรียนคือ 120% หมายความว่ามันจะสร้างดาเมจ 120% ให้ศัตรูที่ชนะทางธาตุ การอัปเกรดอุปกรณ์จะเพิ่มดาเมจชนะทางธาตุหลักของออโรเรียน\n2. เมื่อธาตุของออโรเรียนแพ้ทาง ดาเมจที่สร้างได้จะคงไว้ที่ 80%",
  str_help_petequip_title3 = "ข้อมูลการปรับแต่งอุปกรณ์",
  str_help_petequip_details3 = "1. อุปกรณ์บางอย่างของ Aurorians สามารถอัพเกรดเพิ่มเติมได้ สิ่งนี้เรียกว่าการปรับแต่งอุปกรณ์\n2. การปรับแต่งอุปกรณ์จะปลดล็อกสำหรับชาว Aurorian เหล่านี้เมื่อพวกเขาไปถึงระดับ Ascension III, Lv.80 และอุปกรณ์ Lv.10\n3.การอัปเกรดระดับการปรับแต่งอุปกรณ์จะเพิ่มค่า ATK, DEF, HP และเอฟเฟกต์ทักษะการต่อสู้ต่างๆ ของ Aurorian",
  str_help_talepettask_title1 = "การได้รับออโรเรียนในตำนาน",
  str_help_talepettask_details1 = "1. เลือกอัญเชิญออโรเรียนในตำนานหนึ่งราย รายการเควสต์อัญเชิญสำหรับออโรเรียนที่เลือกจะแสดงขึ้นมา เมื่อทำเควสต์ทั้งหมดสำเร็จแล้ว คุณจะได้รับออโรเรียน\n2. เมื่อคุณได้รับออโรเรียนในตำนาน จะอัปเกรดเป็นขั้น III โดยอัตโนมัติ",
  str_help_talepettask_title2 = "อัญเชิญออโรเรียนในตำนาน",
  str_help_talepettask_details2 = "1. สามารถอัญเชิญออโรเรียนในตำนานได้ครั้งละหนึ่งรายเท่านั้น โดยความคืบหน้าเควสต์จะนับเฉพาะออโรเรียนในตำนานที่เลือกเท่านั้น ส่วนความคืบหน้าเควสต์อัญเชิญของออโรเรียนรายอื่นจะถูกล็อกเมื่ออัญเชิญออโรเรียนในตำนานรายใดรายหนึ่งอยู่\n2. การเปลี่ยนออโรเรียนในตำนานที่อัญเชิญอยู่จะล้างความคืบหน้าเควสต์ขั้นสูงสุดในปัจจุบัน แต่เควสต์ขั้นที่ทำสำเร็จแล้วจะไม่ถูกล้าง เวลาเปลี่ยนต้องระวังให้ดีนะ!",
  str_help_talepetlevel_title1 = "สวนสวรรค์",
  str_help_talepetlevel_details1 = "1. การต่อสู้ในสวนสวรรค์ ออโรเรียนจะได้พลังดวงดาวเพิ่ม ทำให้ได้รับพลังมากกว่าปกติ",
  str_help_talepetlevel_title2 = "เอเพ็กซ์",
  str_help_talepetlevel_details2 = "1. ได้รับรีกัล, ฟรอสต์ไฟร์, มิธอส และเรเควียมเพื่อปลดล็อกที่แห่งความทรงจำ, เอเพ็กซ์",
  str_help_eve_title1 = "อีเวนต์เริ่มต้นขึ้นแล้ว!",
  str_help_eve_title2 = "รางวัลอีเวนต์",
  str_help_eve_details1 = "ด่านอีเวนต์จะแบ่งออกเป็นสองขั้น ซึ่งจะปลดล็อกตามเวลาที่กำหนด",
  str_help_eve_details2 = "คุณสามารถรับตราประแจน็อตได้จากด่านอีเวนต์ ซึ่งนำไปแลกไอเทมในร้านไฮเวย์ได้\nเมื่ออีเวนต์สิ้นสุดลง ตราประแจน็อตที่เหลือจะแปลงเป็นไนท์เทียมตามอัตราแลกเปลี่ยนของร้านค้า\nคุณจะได้รับรางวัลตามความคืบหน้าความสำเร็จเควสต์อีเวนต์ที่สะสมได้",
  str_help_sakura_title1 = "ข้อมูลดารุมะ สแมช",
  str_help_sakura_details1 = "1. อีเวนต์นี้มีกองรางวัล 5 กอง แต่ละกองจับรางวัลได้สูงสุด 100 ครั้ง\n2. ใช้กลีบซากุระเมฆาเพื่อจับรางวัล\n3. คุณสามารถปลดล็อกกองใหม่ได้โดยการจับรางวัลใหญ่ของกองปัจจุบัน แต่จะยังมีสิทธิ์จับรางวัลจากกองรางวัลก่อนหน้า\n4. หลังจากอีเวนต์ดารุมะ สแมชสิ้นสุดลง กลีบซากุระเมฆาที่เหลือจะแปลงเป็นไนท์เทียมในอัตรา 1 ต่อ 30",
  str_help_talepettask_title3 = "พัฒนาการออโรเรียนในตำนาน",
  str_help_talepettask_details3 = "1. พัฒนาการออโรเรียนในตำนานจะต้องใช้ฮาร์ทสโตนและตราดวงดาว พัฒนาการสามารถแบ่งได้เป็น 6 ขั้น จำนวนตราดวงดาวที่ใช้ในแต่ละขั้น คือ 1, 1, 2, 1, 2 และ 3\n2. คุณสามารถรับตราดวงดาวได้จากร้านดวงดาวและอีเวนต์ในอนาคต",
  str_help_battlepass_tittle1 = "หนังสืออีเวนต์พิเศษ",
  str_help_battlepass_tittle2 = "เลเวลและเวลา",
  str_help_battlepass_tittle3 = "ขั้นสูง",
  str_help_battlepass_details1 = "หนังสืออีเวนต์พิเศษที่มีเควสต์และรางวัลหลากหลาย คุณสามารถรับคะแนนการมีส่วนร่วมโดยการทำเควสต์ในหนังสืออีเวนต์นี้ให้สำเร็จ เพิ่มเลเวลของหนังสือ และรับรางวัลโดยการสะสมคะแนนการมีส่วนร่วม",
  str_help_battlepass_details2 = "1. หนังสืออีเวนต์พิเศษมีขีดจำกัดเลเวล เมื่อถึงเลเวลสูงสุดแล้ว เลเวลของหนังสือจะไม่เพิ่มขึ้นอีกต่อไป\n2. หนังสืออีเวนต์พิเศษยังมีเวลาจำกัดอีกด้วย เมื่อเวลาสิ้นสุดลง หนังสืออีเวนต์พิเศษจะปิด",
  str_help_battlepass_details3 = "1. หนังสืออีเวนต์พิเศษพื้นฐานจะปลดล็อกเป็นค่าเริ่มต้น และคุณจะได้รับรางวัลตามเลเวลของหนังสือ\n2. เมื่อซื้อหนังสืออีเวนต์พิเศษขั้นสูงหรือดีลักซ์ คุณจะได้รับรางวัลขั้นสูงตามเลเวลนั้น ๆ",
  str_help_summerminigame_tittle = "ข้อมูลอีเวนต์",
  str_help_summerminigame_tittle1 = "ทำเครื่องดื่มเย็น",
  str_help_summerminigame_tittle2 = "อารมณ์ของลูกค้า",
  str_help_summerminigame_tittle3 = "โบนัสเรตติ้ง",
  str_help_summerminigame_tittle4 = "ความเย็นที่เร้าใจ",
  str_help_summerminigame_details1 = "1. ซุ้มเครื่องดื่มเย็นเปิดให้บริการแล้ว! ยิ่งทำออเดอร์เสร็จภายในเวลาที่กำหนดได้มากเท่าไร ยิ่งได้รับคะแนนเรตติ้งมากขึ้นเท่านั้น\n2. การทำเครื่องดื่มเย็นจะต้องสำเร็จครบ 4 ขั้นตอน ได้แก่ เลือกขนาด ส่วนผสม เครื่องดื่ม และเสิร์ฟให้ลูกค้า ทั้งนี้ลำดับในการเลือกส่วนผสมและเครื่องดื่มไม่มีผลใด ๆ",
  str_help_summerminigame_details2 = "ลูกค้าแต่ละคนมีเวลารอได้ระยะหนึ่ง เมื่อรอนานขึ้น อารมณ์ของพวกเขาจะลดลงจากมีความสุขเป็นใจร้อน จนกระทั่งโกรธ\nยิ่งลูกค้าอารมณ์ดีเท่าไร คุณจะยิ่งได้รับคะแนนเรตติ้งสำหรับออเดอร์มากขึ้นเท่านั้น",
  str_help_summerminigame_details3 = "ในการท้าทายหนึ่งครั้ง ยิ่งทำออเดอร์เสร็จติดต่อกันได้มากเท่าไร โบนัสเรตติ้งจะยิ่งสูงขึ้นเท่านั้นเมื่อเสร็จสมบูรณ์",
  str_help_summerminigame_details4 = "การทำออเดอร์เสร็จติดต่อกันตามจำนวนที่กำหนดจะทำให้เกิด Chill Thrill ในช่วงที่ Chill Thrill กำลังทำงาน คุณสามารถแตะที่ใดก็ได้บนหน้าจอเพื่อทำออเดอร์แต่ละขั้นตอนให้เสร็จโดยอัตโนมัติ และสะสมคะแนนเรตติ้งอย่างรวดเร็ว!",
  str_help_summer_activity_two_title1 = "ข้อมูลการปลดล็อกเอนด์เกม",
  str_help_summer_activity_two_title2 = "ข้อมูลด่านเอนด์เกม",
  str_help_summer_activity_two_details1 = "1. เมื่ออีเวนต์เริ่มขึ้น การท้าทายเอนด์เกมจะปลดล็อกวันละ 1 ชุด\n2. 4 ด่านแรกจะเป็นเลเวลทั่วไป ส่วนด่านที่ 5 จะเป็นด่านเอนด์เกม\n3. เอนด์เกมด่านสุดท้ายคือกษัตริย์ผู้โดดเดี่ยว จะปลดล็อกในวันที่ 6",
  str_help_summer_activity_two_details2 = "1. การท้าทายเอนด์เกมสามารถเล่นซ้ำได้\n2. คุณสามารถเลือกความยากและกลยุทธ์เอนด์เกมของด่านเอนด์เกมได้\n3. คุณจะได้รับคะแนนเอนด์เกมและคะแนนโบนัสเมื่อได้คะแนนทำลายสถิติครั้งใหม่",
  str_help_summer_activity_two_title3 = "ข้อมูลระดับความยาก",
  str_help_summer_activity_two_details3 = "1. คุณสามารถเลือกความยากและกลยุทธ์เอนด์เกมของด่านเอนด์เกมแต่ละด่านได้\n2. ความยากแต่ละระดับจะให้คะแนนพื้นฐานที่สัมพันธ์กัน ยิ่งความยากมากขึ้นเท่าไร ก็ยิ่งได้รับคะแนนมากขึ้นเท่านั้น\n3. กลยุทธ์เอนด์เกมแต่ละอย่างมีตัวคูณคะแนนที่สัมพันธ์กัน ยิ่งคุณเลือกกลยุทธ์เอนด์เกมมากเท่าไร ก็ยิ่งได้รับตัวคูณคะแนนโดยรวมมากขึ้นเท่านั้น ตัวคูณคะแนนพื้นฐานคือ 100%\n4. คะแนนเอนด์เกมรวมที่ได้รับ = คะแนนพื้นฐาน x ตัวคูณคะแนน",
  str_help_world_boss_title1 = "โหมด Codex ความอ้างว้าง",
  str_help_world_boss_details1 = "1.ในโหมด Desolation Codex คุณสามารถท้าทายบอสศัตรูที่แตกต่างกันในแต่ละรอบกิจกรรม บอสมี HP ไม่จำกัด และคุณจะได้รับอันดับและรางวัลที่เกี่ยวข้องตามความเสียหายที่คุณจัดการ\n2.คุณจะได้รับการเลื่อนระดับจากระดับ Bronze เป็นระดับ Paragon โดยพิจารณาจากความเสียหายทั้งหมดที่คุณทำได้สูงสุด เมื่อความเสียหายปัจจุบันของคุณถึงจำนวนที่กำหนด คุณจะได้รับระดับ Paragon หลังจากไปถึงพารากอนแล้ว หากคุณเป็นหนึ่งในผู้เล่น 999 อันดับแรกที่มีผลการท้าทายสูงสุด คุณจะได้รับเลื่อนตำแหน่งเป็นระดับตำนาน\n3.Forgotten Whispers และ Forgotten Utterances ที่ได้รับจาก Desolation Codex สามารถแลกเปลี่ยนเป็นไอเทมหายากได้ที่ Exiled Harborage",
  str_help_world_boss_title2 = "ขบวนทัพสงครามลัทธิ",
  str_help_world_boss_details2 = "1. คุณสามารถใช้หลายทีมเพื่อท้าทายบอส ความเสียหายทั้งหมดที่ทำได้โดยทุกทีมของคุณจะคำนวณเป็นความเสียหายสุดท้ายที่ทำได้\n2.Aurorian แต่ละคนสามารถส่งไปยังทีมเดียวเท่านั้น หากคุณต้องการมอบหมายพวกเขาให้กับทีมอื่น คุณสามารถเลือกที่จะรีเซ็ตสถิติการรบของทีมปัจจุบันได้",
  str_help_world_boss_title3 = "ผลสรุปแรงค์",
  str_help_world_boss_details3 = "1. แต่ละรอบของ Desolation Codex จะมีระยะเวลาที่กำหนดไว้ ณ สิ้นสุดรอบปัจจุบัน ผลลัพธ์จะถูกคำนวณตามอันดับของคุณในเวลานั้น และตราสัญลักษณ์อันดับและรางวัลจะถูกจัดส่งตามอย่างเหมาะสม2. ตราสัญลักษณ์อันดับของคุณจะถูกแสดงบนรูปประจำตัวส่วนตัวของคุณ และตราสัญลักษณ์สำหรับรอบนี้จะถูกกำหนดตามอันดับของคุณในสิ้นสุดรอบก่อนหน้า หากคุณไม่ได้เข้าร่วมท้าทาย Desolation Codex ในรอบนี้ คุณจะไม่ได้รับอันดับในรอบถัดไป และตราสัญลักษณ์ของคุณจะไม่ถูกแสดงบนรูปประจำตัวของคุณ\n3. รางวัลอันดับจะถูกส่งไปยังกล่องจดหมายของคุณ โปรดทราบว่ากระบวนการจัดส่งอาจมีความล่าช้า",
  str_help_world_boss_title4 = "ข้อมูลศัตรู",
  str_help_world_boss_details4 = "1. หลังจากทำดาเมจกับเจ้าของร้านถึงจำนวนหนึ่ง คุณสมบัติของเจ้าของร้านจะได้รับการเสริมพลัง เจ้าของร้านมีการเสริมพลังหลายระดับ\n2. ผลการต่อสู้จะบันทึกเฉพาะดาเมจที่ทำกับเจ้าของร้านเท่านั้น ส่วนดาเมจที่ทำกับศัตรูที่เจ้าของร้านเรียกมาจะไม่นับรวมในการคำนวณ\n3. ออโรเรียนทำดาเมจชนะทางธาตุแรงขึ้น 100%\n4. ศัตรูเจ้าของร้านสามารถต้านดาเมจที่ขึ้นอยู่กับเปอร์เซ็นต์ของ HP ได้",
  str_help_shuoming_aircrafttactic_help_title1 = "ข้อมูลห้องซิมูเลชั่น",
  str_help_shuoming_aircrafttactic_help_desc1 = "1. ห้องซิมูเลชั่นคือห้องสำหรับใช้ดิสก์ข้อมูลและจัดเก็บ ดิสก์ข้อมูลจะสร้างใหม่ฟรีทุกสัปดาห์\n2. คุณสามารถอัปเกรดห้องเพื่อเพิ่มความจุดิสก์ข้อมูลและลดเวลาการสร้างได้\n3. ทั้งยังมอบหมายออโรเรียนให้ประจำการที่นี่ \nเพื่อลดเวลาการสร้างดิสก์ข้อมูลเพิ่มได้อีกด้วย",
  str_help_shuoming_aircrafttactic_help_title2 = "ข้อมูลดิสก์ข้อมูล:",
  str_help_shuoming_aircrafttactic_help_desc2 = "1. เมื่อสร้างดิสก์ข้อมูลสำเร็จแล้ว คุณจะได้รับดิสก์ข้อมูลที่ยังไม่เปิด แตะเพื่อเปิดแล้วดิสก์นี้จะกลายเป็นดิสก์ข้อมูลประเภทหนึ่ง\n2. คุณสามารถเร่งการฟื้นฟูดิสก์ข้อมูลได้ สามารถสร้างดิสก์ข้อมูลได้ฟรีเมื่อมีโอกาสฟรีเหลืออยู่ ไม่อย่างนั้นคุณต้องใช้หิ่งห้อยเพื่อลดเวลาฟื้นฟู ใช้หิ่งห้อยให้เพียงพอ และคุณจะสามารถสร้างดิสก์ข้อมูลใหม่ได้\n3. จำนวนดิสก์ข้อมูลที่คุณครอบครองได้มีจำกัด หากมีครบจำนวนสูงสุดแล้วจะไม่สามารถรับดิสก์ข้อมูลเพิ่มได้อีก หลังจากใช้ดิสก์ข้อมูลจนมีจำนวนต่ำกว่าที่จำกัด คุณจึงจะรับดิสก์ข้อมูลเพิ่มอีกได้\n4. คุณสามารถลบดิสก์ข้อมูลได้ด้วยตัวเอง แต่เมื่อลบแล้วจะกู้คืนกลับมาไม่ได้",
  str_help_shuoming_aircrafttactic_help_title3 = "ข้อมูลการเล่นคลังข้อมูลคำสั่ง:",
  str_help_shuoming_aircrafttactic_help_desc3 = "1. ในเครื่องจำลองวางแผน คุณสามารถเลือกดิสก์ข้อมูลประเภทต่างๆ เพื่อต่อสู้ได้ และดิสก์ข้อมูลแต่ละประเภทจะสอดคล้องกับสถานการณ์การต่อสู้\n2. สถานการณ์เหล่านี้มีสถานการณ์การต่อสู้แบบต่าง ๆ และการต่อสู้ที่เคยผ่านมาแล้วก็มีโอกาสจะปรากฏที่นี่อีกครั้ง\n3. ในดิสก์ข้อมูลแต่ละอัน คุณสามารถเลือกระดับความยากได้ 3 ระดับ ความยากยิ่งมาก EXP ผู้บัญชาการที่จะได้รับก็มากตามเมื่อคุณผ่านด่านได้สำเร็จ\n4. ดิสก์ข้อมูลจะถูกหักงานหลังจากผ่านด่านได้แล้ว แต่จะไม่เสียดิสก์ข้อมูลหากไม่ผ่านหรือแพ้",
  str_help_shuoming_aircrafttactic_help_title4 = "ข้อมูลเลเวลผู้บัญชาการ:",
  str_help_shuoming_aircrafttactic_help_desc4 = "1. สามารถรับ EXP ผู้บัญชาการได้โดยการผ่านดิสก์ข้อมูลใดก็ได้\n2. เลเวลผู้บัญชาการของคุณจะเพิ่มขึ้นอัตโนมัติเมื่อคุณมี EXP ผู้บัญชาการสะสมถึงระดับหนึ่ง\n3. หลังจากที่เลเวลผู้บัญชาการของคุณเพิ่มขึ้น คุณจะได้รับรางวัลที่เกี่ยวข้อง\n4. คุณสามารถดูเลเวลผู้บัญชาการของคุณได้ในข้อมูลส่วนตัวและข้อมูลเพื่อน",
  str_help_shuoming_aircrafttactic_help_title5 = "ข้อมูลชิ้นส่วนข้อมูล:",
  str_help_shuoming_aircrafttactic_help_desc5 = "1. เมื่อดิสก์ข้อมูลถูกสร้าง มีโอกาสที่คุณจะได้รับดิสก์ที่มีชิ้นส่วนข้อมูล คุณสามารถรับชิ้นส่วนข้อมูลได้หลังจากผ่านระดับความยากใดก็ได้\n2. ชิ้นส่วนข้อมูลจะแสดงเป็นดรอปพิเศษ\n3. เมื่อข้อมูลทั้งหมดในฐานข้อมูลถูกปลดล็อกแล้ว จะไม่สามารถรับชิ้นส่วนข้อมูลได้อีกเมื่อสร้างดิสก์ข้อมูล",
  str_help_shuoming_aircrafttactic_help_title6 = "ข้อมูลฐานข้อมูล:",
  str_help_shuoming_aircrafttactic_help_desc6 = "1. ข้อมูลแต่ละประเภทในฐานข้อมูลจะมีเบาะแส 4 ชิ้น\n2. คุณสามารถปลดล็อกเบาะแสข่าวกรองของฐานข้อมูล และรับข่าวกรองได้โดยใช้ชิ้นส่วนข้อมูล\n3. หลังจากปลดล็อกข่าวกรองทั้ง 4 ชิ้นในฐานข้อมูลแล้ว คุณจะได้รับรางวัลข่าวกรอง\n4. ข่าวกรองฐานข้อมูลจะต้องปลดล็อกตามลำดับที่กำหนดเท่านั้น หลังจากปลดล็อกข่าวกรองชุดก่อนหน้าเสร็จสมบูรณ์แล้วจึงจะปลดล็อกชุดต่อไปได้",
  str_help_shuoming_n8_help_title1 = "ข้อมูลการเล่นคลังข้อมูลคำสั่ง (เวอร์ชันทดสอบ)",
  str_help_shuoming_n8_help_desc1 = "1. คลังข้อมูลคำสั่ง (เวอร์ชันทดสอบ) คือเครื่องจำลองวางแผนกลยุทธ์ที่ถูกซ่อมขึ้นมาโดยกรอนรู\n2. ในเครื่องจำลองวางแผน คุณสามารถเลือกดิสก์ข้อมูลประเภทต่าง ๆ เพื่อต่อสู้ได้ และดิสก์ข้อมูลแต่ละประเภทจะสอดคล้องกับสถานการณ์การต่อสู้\n3. สถานการณ์เหล่านี้มีสถานการณ์การต่อสู้แบบต่าง ๆ และการต่อสู้ที่เคยผ่านมาแล้วก็มีโอกาสจะปรากฏที่นี่อีกครั้ง\n4. ในดิสก์ข้อมูลแต่ละประเภท คุณสามารถเลือกระดับความยากได้ 3 ระดับ ความยากยิ่งมาก กิตติศัพท์ที่จะได้รับก็มากตามเมื่อคุณผ่านได้สำเร็จ\n5. ดิสก์ข้อมูลจะถูกหักงานหลังจากผ่านด่านได้แล้ว แต่จะไม่เสียดิสก์ข้อมูลหากไม่ผ่านหรือแพ้",
  str_help_shuoming_n8_help_title2 = "การรับดิสก์ข้อมูล:",
  str_help_shuoming_n8_help_desc2 = "ข้อมูลการได้รับดิสก์ข้อมูล\n1. คุณจะได้รับดิสก์ข้อมูลจำนวนหนึ่งเมื่อเริ่มอีเวนต์\n2. หลังจากอีเวนต์เริ่มต้น คุณจะได้รับดิสก์ข้อมูลเป็นระยะ\n3. จำนวนดิสก์ข้อมูลที่คุณครอบครองได้จะมีจำกัด หากคุณมีครบจำนวนสูงสุดแล้ว คุณจะไม่สามารถรับดิสก์ข้อมูลเพิ่มได้อีก หลังจากใช้ดิสก์ข้อมูลเพื่อลดจำนวนลงไปต่ำกว่าจำนวนสูงสุด คุณจะสามารถรับมันได้ต่อไป\n4. ดิสก์ข้อมูลสามารถลบได้ด้วยตัวเอง แต่เมื่อลบแล้วจะไม่สามารถกู้คืนกลับมาได้",
  str_help_data_title = "ข้อมูลฐานข้อมูล:",
  str_help_data_desc = "1. ข้อมูลแต่ละประเภทในฐานข้อมูลจะมีเบาะแส 4 ชิ้น\n2. คุณสามารถปลดล็อกเบาะแสข่าวกรองของฐานข้อมูล และรับข่าวกรองได้โดยใช้ชิ้นส่วนข้อมูล\n3. หลังจากปลดล็อกข่าวกรองทั้ง 4 ชิ้นในฐานข้อมูลแล้ว คุณจะได้รับรางวัลข่าวกรอง\n4. ข่าวกรองฐานข้อมูลสามารถปลดล็อกได้ตามลำดับที่กำหนดเท่านั้น หลังจากปลดล็อกข่าวกรองชุดก่อนหน้าเสร็จสมบูรณ์แล้วจึงจะปลดล็อกชุดต่อไปได้",
  str_help_shuoming_blackunderbellydungeon_help_title1 = "ข้อมูลแหล่งกบดานทมิฬ รัตติกาลสีขาว",
  str_help_shuoming_blackunderbellydungeon_help_desc1 = "1. เมื่อเคลียร์ด่าน White Night, Black Underbelly ได้ตามจำนวนที่กำหนด เวลาโบนัสจะเปิดใช้งาน ซึ่งจะมี Corrupted Eclipsites ในสนามรบ เอาชนะพวกเขาเพื่อรับ Nightium เพิ่ม\n2.ด่านที่เคลียร์ในระดับความยากต่างกันใน White Night, Black Underbelly จะถูกบันทึกแยกกัน\n3.ด่านจะถูกนับแยกจากกัน เมื่อใช้ Carrier ในการกวาด",
  str_help_shuoming_fengxinta_title = "ข้อมูลหอคอยไฮยาซินท์",
  str_help_shuoming_fengxinta_desc = "1. เมื่อคุณได้รับดีไซน์เฟอร์นิเจอร์หรือสิ่งปลูกสร้าง จะสามารถการผลิตไอเทมที่เกี่ยวข้องได้ในหอคอยไฮยาซินท์\n2. การผลิตต้องใช้วัสดุที่กำหนด เมื่อการผลิตเสร็จสมบูรณ์แล้ว คุณจะสามารถรับไอเทมนั้นได้\n3. เพิ่มเลเวลสวนลอยฟ้าเพื่อปลดล็อกคิวการผลิตเพิ่มเติมและเพิ่มผลิตภาพให้สูงขึ้น",
  str_help_shuoming_baifang_title1 = "เพื่อนเข้าชม",
  str_help_shuoming_baifang_desc1 = "1. เมื่อเพื่อนมีสวนลอยฟ้า คุณจะสามารถไปเยี่ยมชมได้\n2. ขณะเยี่ยมชมสวนลอยฟ้าของเพื่อน คุณสามารถดำเนินการบางอย่างได้ อย่างเช่นเร่งการผลิตของเพื่อน รดน้ำต้นไม้มหัศจรรย์ และรับไอเทมจากกล่องไอเทมของเพื่อนได้",
  str_help_shuoming_baifang_title2 = "เร่งความเร็วการผลิตและรดน้ำต้นไม้",
  str_help_shuoming_baifang_desc2 = "1. เมื่อมีไอเทมหรือต้นไม้มหัศจรรย์ที่เร่งความเร็วได้ในสวนลอยฟ้าของเพื่อน อย่าลืมเร่งความเร็วหรือรดน้ำต้นไม้ให้เพื่อนของคุณด้วยนะ!\n2. ไอเทมแต่ละชิ้นที่อยู่ระหว่างการผลิตสามารถเร่งความเร็วได้วันละครั้งเท่านั้น\n3. ผืนดินสมบูรณ์แต่ละแปลงรดน้ำได้วันละ 1 ครั้งเท่านั้น",
  str_help_shuoming_baifang_title3 = "กล่องไอเทมสวนลอยฟ้า",
  str_help_shuoming_baifang_desc3 = "1. ผู้นำทางสามารถนำไอเทมไปใส่ไว้ในกล่องไอเทมในสวนลอยฟ้าของตนเองได้\n2. ขณะไปเยี่ยมชมสวนลอยฟ้าของเพื่อน ผู้นำทางสามารถรับไอเทมได้หนึ่งช่องจากกล่องไอเทมของเพื่อน\n3. ผู้นำทางสามารถรับไอเทมจากเพื่อนแต่ละคนได้เพียงแค่วันละครั้งเท่านั้น\n4. ผู้นำทางสามารถรับไอเทมได้สูงสุดวันละ 10 ครั้ง",
  str_help_shuoming_homelevel_title1 = "การตกแต่งสวนลอยฟ้า",
  str_help_shuoming_homelevel_desc1 = "1. ผู้นำทางสามารถตกแต่งสวนลอยฟ้าได้ด้วยสิ่งปลูกสร้างและต้นไม้มหัศจรรย์\n2. ขณะที่ออโรเรียนที่ได้รับเชิญเข้าพักที่สวนลอยฟ้า สายสัมพันธ์ของออโรเรียนจะเพิ่มขึ้นเมื่อเวลาผ่านไป",
  str_help_shuoming_homelevel_title2 = "การสร้างสิ่งปลูกสร้าง",
  str_help_shuoming_homelevel_desc2 = "สิ่งปลูกสร้างหลายอย่างสามารถสร้างได้โดยใช้หอคอยไฮยาซินท์ที่ตั้งอยู่กลางจัตุรัสเพื่อตกแต่งสวนลอยฟ้า\nการก่อสร้างสิ่งปลูกสร้างต้องใช้ไม้และแร่ ซึ่งกระจายอยู่ในพื้นที่และสามารถหาได้โดยใช้เครื่องมือที่เหมาะสม",
  str_help_shuoming_homelevel_title3 = "การเพาะพันธุ์ต้นไม้มหัศจรรย์",
  str_help_shuoming_homelevel_desc3 = "ต้นไม้มหัศจรรย์คือต้นไม้ประดับที่นำไปไว้ที่สวนลอยฟ้าได้\nการปลูกต้นไม้มหัศจรรย์ทำได้โดยการเพาะเมล็ดในผืนดินสมบูรณ์ ซึ่งหาได้จากหอคอยไฮยาซินท์",
  str_help_shuoming_homelevel_title4 = "การตกปลา",
  str_help_shuoming_homelevel_desc4 = "ปลาหลายชนิดสามารถจับได้ด้วยการตกปลาริมแม่น้ำ\nปลาบางชนิดมีค่ามากและสามารถขายตามคำสั่งซื้อในร้านค้าได้\nปลาหายากบางชนิดเหมาะสำหรับตั้งโชว์ และสามารถนำไปเลี้ยงได้ที่น้ำพุแห่งความหวังในจัตุรัส",
  str_help_shuoming_homelevel_title5 = "การล่าสมบัติ",
  str_help_shuoming_homelevel_desc5 = "การล่าสมบัตรในสวนลอยฟ้าจะมอบโอกาสในการรับหีบและเหรียญแห่งความหวัง\nผู้นำทางสามารถโยนเหรียญแห่งความหวังลงในน้ำพุแห่งความหวังเพื่อเรียนรู้เรื่องราวเบื้องหลังของตนเองได้",
  str_help_shuoming_homelevel_title6 = "ออโรเรียนที่เข้าพัก",
  str_help_shuoming_homelevel_desc6 = "หลังจากก่อสร้างและตกแต่งหอพักในสวนแล้ว ผู้นำทางสามารถเชิญออโรเรียนมาเข้าพักได้\nเมื่อไรก็ตามที่มีออโรเรียนมาเข้าพักที่สวนลอยฟ้า ผู้นำทางสามารถโต้ตอบกับพวกเขาและทำให้เกิดเหตุการณ์ต่าง ๆ ขึ้นได้โดยการสุ่ม",
  str_help_shuoming_homelevel_title7 = "การเยี่ยมเพื่อน",
  str_help_shuoming_homelevel_desc7 = "ผู้นำทางสามารถไปเยี่ยมสวนลอยฟ้าของเพื่อนเพื่อช่วยเร่งความเร็วการก่อสร้างและการเติบโตของต้นไม้มหัศจรรย์ให้เพื่อนได้\nนอกจากนี้ผู้นำทางยังสามารถนำไอเทมไปใส่ในกล่องไอเทมสวนลอยฟ้าของเพื่อนเพื่อให้เพื่อน ๆ ที่มาเยี่ยมชมรับไอเทมได้อีกด้วย",
  str_help_shuoming_breed_desc1 = "การเพาะพันธุ์กลายพันธุ์ การเพาะพันธุ์มุ่งเป้า และการเพาะพันธุ์ดัดแปลงสามารถทำได้ในผืนดินสมบูรณ์\nนำเมล็ดพันธุ์ต้นไม้มหัศจรรย์มาปลูกที่นี่เพื่อเริ่มเพาะพันธุ์ได้เลย หลังจากเพาะพันธุ์ไปช่วงเวลาหนึ่งแล้ว คุณจะได้รับต้นไม้มหัศจรรย์และเมล็ดพันธุ์จากต้นไม้มหัศจรรย์นี้ โดยเมล็ดพันธุ์จำนวนหนึ่งจะดรอปในช่วงระยะเวลาที่กำหนด\nนำต้นไม้มหัศจรรย์ไปวางในสวนลอยฟ้า ซึ่งจะย้อมสีได้ด้วย",
  str_help_shuoming_breed_desc2 = "การเพาะพันธุ์กลายพันธุ์สามารถทำได้โดยใช้เมล็ดพันธุ์ต่างชนิดที่มีระดับความหายากเท่ากันเท่านั้น การเพาะพันธุ์กลายพันธุ์ไม่สามารถทำได้กับต้นไม้มหัศจรรย์ที่ระดับความยากพรีเมียม\nถ้าเมล็ดพันธุ์สองเมล็ดมาจากหมวดหมู่เดียวกัน ต้นไม้มหัศจรรย์ที่ผลิตได้จะเป็นหมวดหมู่เดียวกัน\nถ้าเมล็ดพันธุ์สองเมล็ดมาจากคนละหมวดหมู่กัน จะได้รับต้นไม้ชนิดใดก็ได้ที่อยู่ในสองหมวดหมู่นั้น และมีโอกาสสูงที่จะได้รับต้นไม้มหัศจรรย์ในสกุลเดียวกับเมล็ดพันธุ์หลัก",
  str_help_shuoming_breed_desc3 = "การเพาะพันธุ์กลายพันธุ์มีโอกาสสุ่มผลิตต้นไม้มหัศจรรย์ในระดับความหายากที่สูงขึ้น ต้นไม้มหัศจรรย์ขั้นสูงจะเกิดขึ้นโดยการสุ่มจากต้นไม้ทั้งหมดในหมวดหมู่ต่าง ๆ ที่มาจากเมล็ดพันธุ์หลักและปัจจัยการกลายพันธุ์\nถ้าการอัปเกรดไม่สำเร็จ จะได้รับเมล็ดพันธุ์หลักหรือต้นไม้มหัศจรรย์ตามปัจจัยการกลายพันธุ์แทน",
  str_help_shuoming_breed_desc4 = "ตัวอย่างผลลัพธ์ของการเพาะพันธุ์กลายพันธุ์สามารถดูได้หลังจากกำหนดเมล็ดพันธุ์หลักและปัจจัยการกลายพันธุ์แล้ว",
  str_help_shuoming_breed_desc5 = "การเพาะพันธุ์มุ่งเป้าทำได้โดยใช้เมล็ดพันธุ์ชนิดเดียวกันเท่านั้น การเพาะพันธุ์มุ่งเป้าจะทำให้ได้รับต้นไม้มหัศจรรย์ตามเมล็ดพันธุ์ที่ใช้เสมอ",
  str_help_shuoming_breed_desc6 = "การเข้าไปหาต้นไม้มหัศจรรย์ที่อยู่ในสวนลอยฟ้าจะทำให้ต้นไม้เข้าสู่กระบวนการย้อมสี กระบวนการนี้จะใช้โรสคริสตัลลอยด์ และเปลี่ยนสีของต้นไม้มหัศจรรย์",
  str_help_shuoming_breed_desc7 = "การเพาะพันธุ์ทั้งแบบกลายพันธุ์และมุ่งเป้าจะให้ไอเทมโบนัส: ไม้ศิลา\nจำนวนไม้ศิลาที่ได้รับขึ้นอยู่กับคุณภาพของต้นไม้มหัศจรรย์ โดยรับได้สูงสุดสัปดาห์ละ 100",
  str_help_shuoming_breed_desc8 = "ใช้ต้นไม้มหัศจรรย์ IV x1 กับ น้ำยาดัดแปลง x1 ในการเพาะพันธุ์ดัดแปลง จะเกิดเป็นต้นไม้มหัศจรรย์ IV ชนิดอื่นในสายพันธุ์เดียวกัน",
  str_help_shuoming_breed_title1 = "ผืนดินสมบูรณ์และต้นไม้มหัศจรรย์",
  str_help_shuoming_breed_title2 = "กฎการเพาะพันธุ์กลายพันธุ์",
  str_help_shuoming_breed_title3 = "กฎการอัปเกรด",
  str_help_shuoming_breed_title4 = "ดูตัวอย่างผลการเพาะพันธุ์",
  str_help_shuoming_breed_title5 = "กฎการเพาะพันธุ์มุ่งเป้า",
