  str_help_shuoming_breed_title8 = "กติกาการเพาะพันธุ์ดัดแปลง",
  str_help_homeland_wishing_title1 = "ข้อมูลน้ำพุแห่งความหวัง",
  str_help_homeland_wishing_title2 = "การเก็บเหรียญแห่งความหวัง",
  str_help_homeland_wishing_title3 = "การเลี้ยงปลาสวยงาม",
  str_help_homeland_wishing_desc1 = "1. ว่ากันว่าเคเลสไทต์มีประเพณีที่ไม่เป็นทางการอยู่อย่างหนึ่ง คือ เคเลสไทต์ที่กำลังจะโตเป็นผู้ใหญ่ต้องโยนเหรียญแห่งความหวังที่ทำขึ้นมาด้วยตัวเองลงไปในน้ำพุแห่งความหวังและอธิษฐาน ประเพณีนี้ถูกลืมไปพร้อมกับการหายตัวไปของชาวเคเลสไทต์ และแม้แต่เหรียญแห่งความหวังของพวกเขาก็ยังหายไปอย่างไร้ร่องรอยด้วยเช่นกัน...\n2. มีโอกาสได้รับเหรียญแห่งความหวังขณะตกปลา",
  str_help_homeland_wishing_desc2 = "1. เหรียญแห่งความหวังที่ได้รับในสวนลอยฟ้าสามารถนำไปโยนลงในน้ำพุแห่งความหวังเพื่อเก็บสะสมได้\n2. คุณจะได้รับรางวัลตามจำนวนเหรียญแห่งความหวังที่โยนลงไปในน้ำพุแห่งความหวัง",
  str_help_homeland_wishing_desc3 = "1. ปลาคุณภาพสูงที่คุณจับได้นั้นสามารถนำไปเลี้ยงในน้ำพุแห่งความหวังได้\n2. ปลาที่เลี้ยงสามารถเก็บกลับออกมาได้ทุกเมื่อโดยไม่กระทบกับการขาย",
  str_help_shuoming_visitfriends_title1 = "ข้อมูลรายชื่อบ้าน",
  str_help_shuoming_visitfriends_title2 = "ข้อมูลรายชื่อบ้าน 1",
  str_help_shuoming_visitfriends_title3 = "ข้อมูลรายชื่อบ้าน 2",
