  str_help_diff_mission_title1 = "กล่องแพนโดร่า",
  str_help_diff_mission_title2 = "ถ้วยรางวัลการท้าทาย",
  str_help_diff_mission_title3 = "การจัดทีมท้าทาย",
  str_help_diff_mission_title4 = "ลักษณะสนามรบ",
  str_help_diff_mission_title5 = "ข้อมูลศัตรู",
  str_help_diff_mission_desc1 = "1. โหมดกล่องแพนโดร่าเป็นด่านระดับยากมาก ซึ่งจะมีกลไกและบอสต่าง ๆ หลากหลายให้ผู้นำทางเข้าไปท้าทาย\n2. ในแต่ละบทของกล่องแพนโดร่าจะมีจุดจอดบนเส้นทางหลายจุด ในแต่ละจุดก็มีด่านต่าง ๆ โดยไม่ได้เรียงลำดับ ผู้นำทางสามารถเข้าท้าทายด่านไหนก็ได้ภายในจุดจอด\n3. ในจุดจอดแต่ละจุดมีถ้วยรางวัลท้าทาย 3–5 ถ้วย ผู้นำทางต้องผ่านด่านโดยใช้ทีมตามเงื่อนไขที่กำหนดเท่านั้นจึงจะได้รับถ้วยรางวัลและรางวัลนั้น ๆ\n4. เมื่อท้าทายด่านต่าง ๆ ในจุดจอดเดียวกัน ผู้นำทางต้องใช้ออโรเรียนที่ไม่ซ้ำกัน",
  str_help_diff_mission_desc2 = "1. จุดจอดแต่ละจุดมีถ้วยรางวัลท้าทาย 3–5 ถ้วย โดยถ้วยรางวัลต่าง ๆ มีเงื่อนไขการท้าทายที่ต่างกัน\n2. ผู้นำทางต้องผ่านทุกด่านในจุดจอดโดยใช้ทีมตามเงื่อนไขที่กำหนดเท่านั้นจึงจะได้รับถ้วยรางวัลและรางวัลนั้น ๆ\n3. เนื่องจากไม่มีการเรียงลำดับถ้วยรางวัล ผู้นำทางจึงเข้าท้าทายถ้วยรางวัลได้หลายครั้งตามต้องการ\n4. เมื่อได้รับถ้วยรางวัลการท้าทายแล้ว ถ้วยจะยังคงอยู่แม้ว่าจะรีเซ็ตทีมใหม่ก็ตาม",
  str_help_diff_mission_desc3 = "1. แต่ละด่านท้าทายได้ทีมเดียวเท่านั้น\n2. ออโรเรียนที่ใช้ไปแล้ว จะใช้ซ้ำในด่านอื่นที่อยู่ในจุดจอดเดียวกันไม่ได้ แต่ใช้ซ้ำอีกได้ในจุดจอดอื่น ๆ\n3. สามารถรีเซ็ตทีมได้ และการรีเซ็ตทีมจะไม่มีผลต่อถ้วยรางวัลการท้าทายที่ได้รับแล้ว",
  str_help_diff_mission_desc4 = "แต่ละด่านมีลักษณะสนามรบเฉพาะตัว ซึ่งทำให้ด่านและมอนสเตอร์ทั้งหลายมีกลไกแตกต่างกัน ผู้นำทางสามารถดูรายละเอียดของลักษณะสนามรบได้ที่หน้าด่านเพื่อเตรียมพร้อมล่วงหน้า",
  str_help_diff_mission_desc5 = "ผู้นำทางสามารถดูรายละเอียดของลักษณะสนามรบได้ที่หน้าด่าน รวมทั้งข้อมูลศัตรูในด่าน เช่น ธาตุและรูปร่างหน้าตาของศัตรูที่ต้องเจอ",
  str_help_shuoming_tanbao_title1 = "รับสัญญาณ",
  str_help_shuoming_tanbao_title2 = "นักสำรวจชับบ์",
  str_help_shuoming_tanbao_title3 = "เครื่องตรวจจับพกพา",
  str_help_shuoming_tanbao_title4 = "ระบุที่ตั้งขุมทรัพย์",
  str_help_shuoming_tanbao_desc1 = "1. โหมด \"ค้นหาพิกัด\" ต้องใช้สัญญาณพิเศษหรือสัญญาณปกติ\n2. หลังจากค้นหาพิกัดเปิดให้เล่น ผู้นำทางทุกคนจะได้รับสัญญาณพิเศษ ×1 และสัญญาณปกติ ×2 ในตอนแรก\n3. ตั้งแต่วันที่ 2 ของอีเวนต์ ผู้นำทางจะได้รับสัญญาณพิเศษ ×1 และสัญญาณปกติ ×2 ทุกวัน รวมเป็นรับได้สูงสุด สัญญาณพิเศษ ×6 และสัญญาณปกติรวม ×12 ในช่วงอีเวนต์",
  str_help_shuoming_tanbao_desc2 = "1. หลังจากโหมด \"ค้นหาพิกัด\" เริ่มขึ้น นักสำรวจชับบ์จะปรากฏบริเวณจัตุรัสไฮยาซินท์ในสวนลอยฟ้า\n2. ตามหานักสำรวจชับบ์ที่จัตุรัสไฮยาซินท์ให้เจอและพูดคุยกับเขา เพื่อเริ่มใช้สัญญาณในการค้นหา\n3. ระบุพิกัดขุมทรัพย์โดยอาศัยการนำทางของสัญญาณภายในเวลาที่กำหนดเพื่อทำการค้นหาให้เสร็จสมบูรณ์ มิฉะนั้นจะถือว่าล้มเหลว",
  str_help_shuoming_tanbao_desc3 = "1. สมบัติกระจัดกระจายไปทั่ว Cloud Gardens ในระหว่างการสืบสวน Navigators สามารถสแกนและค้นหาสมบัติด้วยเครื่องตรวจจับแบบพกพา\n2.เครื่องตรวจจับแบบพกพาจะปล่อยสีต่างๆ ตามระยะทางที่ผู้นำทางเข้าใกล้สมบัติ (จากไกลไปใกล้): สีแดง สีเหลือง และสีเขียว\n3.เครื่องตรวจจับแบบพกพาสามารถสแกนตำแหน่งคร่าวๆของสมบัติได้ มันจะให้ข้อเสนอแนะผ่านมุมการสแกนตามระยะทางไปยังสมบัติ ยิ่งเข้าใกล้มากเท่าไร มุมการสแกนก็จะยิ่งแคบลง จนกระทั่งสามารถระบุตำแหน่งของสมบัติได้",
  str_help_shuoming_tanbao_desc4 = "1. เมื่อเครื่องตรวจจับพกพาตรวจพบ ขุมทรัพย์จะเปล่งแสงจาง ๆ ออกมา\n2. แสงดังกล่าวจะแตกต่างกันไปตามประเภทสัญญาณที่ใช้ในการค้นหา\n3. เมื่อผู้นำทางพบขุมทรัพย์ ให้แตะที่ขุมทรัพย์ แล้วชัยชนะก็จะเป็นของคุณ! รับรางวัลที่สอดคล้องไปเลย!",
  str_help_n20minigame_tittle1 = "ทำอุด้ง",
  str_help_n20minigame_tittle2 = "อารมณ์ของลูกค้า",
  str_help_n20minigame_tittle3 = "โบนัสเรตติ้ง",
  str_help_n20minigame_tittle4 = "อุด้งไร้เทียมทาน",
  str_help_n20minigame_details1 = "1. รถอาหารเปิดให้บริการแล้ว! ยิ่งทำออเดอร์เสร็จภายในเวลาที่กำหนดได้มากเท่าไร ยิ่งได้คะแนนเรตติ้งมากขึ้นเท่านั้น\n2. การทำอุด้งจะต้องสำเร็จครบ 4 ขั้นตอน ได้แก่ เลือกขนาด ส่วนผสม น้ำซุป และเสิร์ฟให้ลูกค้า ทั้งนี้ลำดับในการเลือกส่วนผสมและน้ำเชื่อมจะไม่มีผลใด ๆ",
  str_help_n20minigame_details2 = "ลูกค้าแต่ละคนมีเวลารอได้ระยะหนึ่ง เมื่อรอนานขึ้น อารมณ์ของพวกเขาจะลดลงจากมีความสุขเป็นใจร้อน จนกระทั่งโกรธ\nยิ่งลูกค้าอารมณ์ดีเท่าไร คุณจะยิ่งได้รับคะแนนเรตติ้งสำหรับออเดอร์มากขึ้นเท่านั้น",
  str_help_n20minigame_details3 = "ในการท้าทายหนึ่งครั้ง ยิ่งทำออเดอร์เสร็จติดต่อกันได้มากเท่าไร โบนัสเรตติ้งจะยิ่งสูงขึ้นเท่านั้นเมื่อเสร็จสมบูรณ์",
  str_help_n20minigame_details4 = "การทำออเดอร์เสร็จติดต่อกันตามจำนวนที่กำหนดจะเกิดช่วงเวลาอุด้งไร้เทียมทาน ในช่วงนี้คุณสามารถแตะที่ใดก็ได้บนหน้าจอเพื่อทำออเดอร์แต่ละขั้นตอนให้เสร็จโดยอัตโนมัติ และสะสมคะแนนเรตติ้งอย่างรวดเร็ว!",
  str_help_activity_review_tittle1 = "ข้อมูลความทรงจำการเดินทาง",
  str_help_activity_review_desc1 = "1. คุณสามารถใช้ Cloud Disks เพื่อปลดล็อก Travel Memories\n2. คุณจะได้รับ 1 Cloud Disk เมื่อถึง 60 กิจกรรมทุกวัน\n3. คลาวด์ดิสก์จะไม่สะสมอีกต่อไปเมื่อถึงขีดจำกัด",
  str_help_sailing_explain = "สู่ขุมนรก",
  str_help_sailing_title1 = "อันเดอร์ซิตี้ π",
  str_help_sailing_title2 = "เครื่องช่วยหายใจ",
  str_help_sailing_title3 = "ทีมสำรวจ",
  str_help_sailing_title4 = "เครื่องช่วยหายใจนับ",
  str_help_sailing_details1 = "ซากปรักหักพังที่ค้นพบโดยสหพันธ์อิลลูมินาเมื่อประมาณสามทศวรรษที่แล้ว หลังจากใช้แรงงานและทรัพยากรจำนวนมหาศาลเพื่อสร้างมันขึ้นมาใหม่ สหพันธ์ก็เริ่มเจาะลึกเข้าไปในส่วนลึกที่ดูเหมือนไม่มีที่สิ้นสุดของ Undercity โดยหวังว่าจะค้นพบความรู้เพิ่มเติมเกี่ยวกับอารยธรรมโบราณของ Astra อย่างไรก็ตาม เมื่อสิบปีที่แล้ว ซากปรักหักพังถูกโจมตีโดยกองทัพสุริยุปราคาซึ่งได้รับคำสั่งจากสุริยุปราคา หลังจากน้ำท่วมระบบระบายอากาศของ Undercity ด้วยก๊าซพิษ คลื่นแล้วคลื่นของ Eclipsites สังหารก็เริ่มเทลงในซากปรักหักพัง หยุดการสำรวจทะเยอทะยานของ Illumina Federation ได้อย่างมีประสิทธิภาพ เมื่อต้องเผชิญกับสัตว์ประหลาดกระหายเลือดจำนวนมาก สหพันธ์จึงไม่มีทางเลือกอื่นนอกจากต้องต่อสู้ขณะที่พวกมันถอยกลับขึ้นไปบนผิวน้ำ ปิดผนึกทุกชั้นของ Undercity ตลอดทาง เป็นผลให้ Undercity 101 ได้รับการประกาศอย่างไม่ จำกัด และเป็นอันตรายอย่างยิ่งเนื่องจาก Eclipsites นับไม่ถ้วนที่บุกเข้ามาเมื่อทศวรรษที่แล้วยังคงเดินเตร่อยู่บนพื้นในวันนี้ กลัวว่าความลับของอารยธรรมโบราณจะตกไปอยู่ในมือของพวกคนผิด ต่อมาจึงเปลี่ยนชื่อเป็น Undercity π อันเดอร์ซิตี้ที่ไร้ก้นบึ้งซึ่งซ่อนความรู้ที่เล่าขานกันมานานในอดีต...",
  str_help_sailing_details2 = "1. แต่ละชั้นใน Undercity π มีจำนวนเครื่องช่วยหายใจที่ไม่ระบุจำนวน เริ่มต้นที่ชั้น 1 Navigator จะต้องค้นหาเครื่องช่วยหายใจทุกตัวขณะสำรวจ Undercity\n2. Navigator ต้องเปิดใช้งานเครื่องช่วยหายใจทุกเครื่องในแต่ละชั้นของ Undercity เพื่อกำจัดควันพิษและดำเนินการไปยังชั้นถัดไป\n3. เครื่องช่วยหายใจแต่ละเครื่องต้องใช้ Lumina ของ 5 Aurorians เพื่อเปิดใช้งาน สามารถเปิดใช้งานเครื่องช่วยหายใจในลำดับใดก็ได้\n4. โดยการเพิ่มจำนวน \"เปิดใช้งานเครื่องช่วยหายใจทั้งหมด\" นักเดินเรือสามารถรับรางวัลมากขึ้นผ่านทางอินเทอร์เฟซรางวัลการสำรวจ!",
  str_help_sailing_details3 = "1. ทุกชั้นมีเครื่องช่วยหายใจหลายเครื่อง ซึ่งแต่ละชั้นได้รับการปกป้องโดยหัวหน้า Eclipsite ที่ทรงพลัง ด้วยเหตุนี้ ทีม Aurorian 5 คนจึงจำเป็นต้องท้าทายในแต่ละด่าน\n2. Aurorian แต่ละคนสามารถถูกกำหนดให้กับทีมเดียวในชั้นเดียวกันเท่านั้น และไม่สามารถมอบหมายให้กับทีมในด่านอื่นของชั้นได้\n3. การสร้างสเตจสามารถรีเซ็ตได้ Aurorian ที่รูปแบบถูกรีเซ็ตสามารถกำหนดให้กับรูปแบบใดก็ได้บนชั้นปัจจุบัน\n4. ด่านที่เคลียร์แล้วจะต้องถูกทีมรักษาการณ์ไว้ การรีเซ็ตทีมทหารรักษาการณ์ของด่านจะรีเซ็ตสถานะของด่านนั้นจากเคลียร์เป็นไม่ชัดเจน\n5. พื้นจะนับเป็นเคลียร์เมื่อเคลียร์ด่านทั้งหมดแล้ว\n6. การรีเซ็ตรูปแบบทีมของด่านบนพื้นเคลียร์จะไม่เปลี่ยนสถานะการเคลียร์ของชั้นนั้น",
  str_help_sailing_details4 = "1. ตลอดการสำรวจของคุณ เครื่องช่วยหายใจจะถูกแบ่งออกเป็นสองชุด: \"เปิดใช้งานเครื่องช่วยหายใจ\" และ \"เปิดใช้งานเครื่องช่วยหายใจทั้งหมด\"\n2. \"เปิดใช้งานเครื่องช่วยหายใจทั้งหมด\" ระบุจำนวนเครื่องช่วยหายใจสูงสุดที่ระบบนำทางเปิดใช้งานสำหรับการสำรวจนี้ การรีเซ็ตด่าน/พื้นใดๆ จะไม่มีผลกับตัวเลขนี้\n3. \"เครื่องช่วยหายใจที่เปิดใช้งาน\" ระบุจำนวนเครื่องช่วยหายใจที่เปิดใช้งานอยู่ในปัจจุบันสำหรับความพยายามในการสำรวจที่กำหนด การรีเซ็ตสเตจสำหรับชั้นปัจจุบันจะลดจำนวนนี้ การรีเซ็ตขั้นตอนสำหรับพื้นเคลียร์จะไม่มีผลกับตัวเลขนี้",
  str_help_shuoming_property_cultivate_title1 = "ข้อมูลระบบเอนไลต์เทนเมนต์",
  str_help_shuoming_property_cultivate_desc1 = "1. ระบบสติปัญญาเป็นระบบอัพเกรดที่เสริมความสามารถในการต่อสู้ของออโรเรียนทั้งหมด\n2. ระบบสติปัญญาประกอบด้วยโมดูลน้ำ, ไฟ, ป่า, และสายฟ้า โดยแต่ละโมดูลจะเสริมคุณสมบัติของออโรเรียนที่มีธาตุหลักที่สอดคล้องกัน\n3. ระบบสติปัญญาเพิ่ม ATK, DEF, HP, ดาเมจตอบโต้ธาตุ, ดาเมจสกิลใช้งานสุดท้าย และความน่าจะเป็นในการรีเฟรชช่องธาตุของออโรเรียนที่มีธาตุเดียวกัน\n4. การเสริมสร้างของระบบสติปัญญาจะไม่แสดงในหน้าต่าง แต่จะมีผลโดยตรงในการต่อสู้\n5. การเสริมสร้างของระบบสติปัญญาจะไม่มีผลในการเล่นบางส่วน โปรดอ้างอิงข้อมูลเกมที่เกี่ยวข้องเพื่อดูรายละเอียด",
  str_help_shuoming_property_cultivate_title2 = "ข้อมูลการอัปเกรดระบบเอนไลต์เทนเมนต์",
  str_help_shuoming_property_cultivate_desc2 = "1. วัตถุดิบสามารถใช้เพื่อเพิ่มเลเวลโมดูลองค์ประกอบ\n2. โมดูลองค์ประกอบสามารถอัปเกรดหลังจากที่มีเลเวลสูงสุดและเงื่อนไขที่จำเป็นได้รับการตอบสนอง\n3. โมดูลองค์ประกอบสามารถเพิ่มเลเวลขึ้นอีกหลังจากที่ได้รับการอัปเกรด",
  str_help_elimate_explain = "ข้อมูลการฝึกอบรมแสงกระจ่าง",
  str_help_elimate_tittle1 = "ข้อมูลการเล่น",
  str_help_elimate_tittle2 = "ความสัมพันธ์ออโรเรียน",
  str_help_elimate_tittle3 = "สนับสนุนสังกัด",
  str_help_elimate_tittle4 = "รางวัลคะแนน",
  str_help_elimate_tittle5 = "รางวัลเคลียร์ด่าน",
  str_help_elimate_details1 = "1. ในการฝึกฝนที่ได้รับการส่องสว่าง สามารถท้าทายระดับความยากที่หลากหลายได้\n2. ไม่ว่าจะเป็นระดับความยากใด การท้าทายทั้งหมดต้องสำเร็จในจำนวนรอบที่กำหนด และเปอร์เซ็นต์ HP ของ Aurorians จะถูกสืบทอดระหว่างด่าน การท้าทายจะสิ้นสุดถ้าคุณถูกปราบในด่านใด ๆ\n3. Enlightenment Gears ที่มีผลเฉพาะในการท้าทายปัจจุบันสามารถได้รับหลังจากเคลียร์ด่าน ทุก Enlightenment Gears จะถูกนำออกหลังจากการท้าทายสิ้นสุด4. ในด่านการฝึกฝนของ Enlightened ไม่จำเป็นต้องทำการเชื่อมต่อ แทนที่จะเคลียร์ไทล์โดยการแตะ การแตะที่ไทล์จะเลือกไทล์ที่อยู่ติดกันทั้งหมดที่มีสีเดียวกัน การแตะที่ไทล์อีกครั้งจะเคลียร์ไทล์ที่เลือกและ Aurorians จะสร้าง Chain Combo ตามจำนวนของไทล์ที่ถูกเคลียร์",
  str_help_elimate_details2 = "1. ระหว่างการฝึกฝนของ Enlightened, มีความผูกพันระหว่าง Aurorians บางคน\n2. เมื่อ Aurorians ที่มีความผูกพันถูกปรับใช้ในเวลาเดียวกัน, พวกเขาจะได้รับธาตุหลักของกันและกัน หากช่องของธาตุหลักหนึ่งในนี้ถูกลบออก, Aurorians ทั้งสองจะเข้าร่วมการต่อสู้",
  str_help_elimate_details3 = "1. ในการฝึกฝนแบบ Enlightened, แต่ละฝ่ายมีสกิลสนับสนุนฝ่ายที่ไม่ซ้ำกัน\n2. เมื่อมีออโรเรียนจากฝ่ายเดียวกันอย่างน้อย 3 คนถูกปรับใช้งาน การเอาช่อง 15/30 ช่องออกทันทีจะทำให้สกิลฝ่ายระดับ 1/ระดับ 2 ถูกเรียกใช้งาน",
  str_help_elimate_details4 = "1. ในระหว่างการฝึกฝนที่ได้รับการส่งเสริม คะแนนจะได้รับจากการเคลียร์ด่าน ยิ่งระดับความยากสูงขึ้น คะแนนที่ได้รับเมื่อเคลียร์ด่านก็จะมากขึ้น\n2. รางวัลคะแนนสามารถเรียกร้องได้เมื่อสะสมคะแนนเป็นจำนวนที่กำหนดในแต่ละรอบ รางวัลคะแนนจะถูกรีเซ็ตในแต่ละรอบ\n3. ยิ่งระดับความยากที่ปลดล็อคสูงขึ้น รางวัลคะแนนในแต่ละรอบก็จะดีขึ้น และขีดจำกัดสูงสุดของรางวัลคะแนนก็จะสูงขึ้น",
  str_help_elimate_details5 = "1. ระหว่างการฝึกอบรมที่ได้รับการส่งเสริม รางวัลสามารถรับได้หลังจากเคลียร์ด่าน\n2. ในแต่ละระยะเวลา จำนวนและปริมาณของรางวัลเคลียร์ที่สามารถรับได้จะถูกจำกัด และขีด จำกัด นี้จะถูกตั้งค่าใหม่ในทุกระยะเวลา",
  str_help_world_boss_title1_new = "Codex ความรกร้าง: โหมดการรู้ตัว",
  str_help_world_boss_details1_new = "1.ในโหมด Desolation Codex คุณสามารถท้าทายบอสศัตรูแต่ละตัวได้ในแต่ละรอบอีเวนต์ บอสมี HP ไม่จำกัด และคุณจะได้รับแรงค์และรางวัลตามดาเมจที่ทำได้\n2.คุณจะได้เลื่อนขั้นจากแรงค์บรอนซ์เป็น Paragon ตามดาเมจรวมสูงสุดที่คุณทำได้ เมื่อดาเมจปัจจุบันของคุณถึงจำนวนที่กำหนด คุณจะได้เข้าสู่แรงค์ Paragon 1.หลังจากที่คุณไปถึงระดับ Paragon หากคุณอยู่ใน 999 ผู้เล่นที่มีผลการท้าทายสูงสุด คุณจะได้รับการเลื่อนขั้นเป็นระดับตำนาน\n2.Forgotten Whispers และ Forgotten Utterances ที่ได้รับจาก Desolation Codex สามารถแลกเปลี่ยนเป็นไอเท็มหายากที่ Exiled Harborage\n3.ในโหมด Enlightenment ไม่จำเป็นต้องทำการเชื่อมต่อ แต่สามารถลบไทล์โดยการแตะ การแตะที่ไทล์จะเลือกทั้งหมดที่อยู่ใกล้เคียงที่มีสีเดียวกัน การแตะที่ช่องอีกครั้งจะลบช่องที่เลือกออก และออโรเรียนจะร่ายคอมโบต่อเนื่องตามจำนวนช่องที่ถูกลบ",
