  str_help_season1_disc_102 = "แนะนำอีฟในการใช้คะแนนปัญญาของเธอเพื่อชนะโอเมนในฝัน หลังจากที่ควบคุมได้ คุณจะสามารถเข้าถึงเมทามอร์ฟาและชิ้นส่วนตะกอน สิ่งเหล่านี้สามารถนำไปแลกของรางวัลหลากหลายได้ที่ Memory Workshop รวมถึงชุด Once Upon a Springtime",
  str_help_season1_disc_103 = "ทำภารกิจที่มีรายละเอียดในชิ้นส่วนแห่งความทรงจำให้สำเร็จเพื่อรับ Lumamber และเปิดเผยเรื่องราวที่ซ่อนอยู่เกี่ยวกับอีฟ",
  str_help_season1_disc_104 = "ทำภารกิจในโลกแห่งความฝันให้สำเร็จเพื่อรับชุด Stand By Me",
  str_help_season1_disc_105 = "เครื่องประดับเล็ก ๆ น้อย ๆ ที่รวบรวมไว้ในความฝันนั้นอีฟเก็บไว้อย่างระมัดระวังที่นี่",
  str_help_season1_disc_201 = "การตื่นขึ้นในพายุกำลังมาถึงพวกเรา แต่ Omen กำลังขัดขวางการตื่นขึ้นของอีฟ ช่วยเหลืออีฟในการปราบ Omen และรับรางวัลอย่างมากมายสำหรับความสำเร็จ โปรดทราบว่าการท้าทาย Omen แต่ละครั้งจะใช้แต้ม Wit 1 แต้ม",
  str_help_season1_disc_202 = "Omen challenge มีสองระดับความยาก: Reverie และ Nightmare\nแม้ว่า Nightmare จะมอบประสบการณ์ที่ท้าทายยิ่งกว่า แต่ก็ยังให้รางวัลที่เหนือกว่าอีกด้วย หากคุณพบว่า Nightmare ครอบงำเกินไป ลองพิจารณา Reverie ก่อน\nภายในการท้าทาย Omen เดียวกัน ระดับดาวที่สำเร็จใน Nightmare จะถูกซิงโครไนซ์กับ Reverie การได้รับรางวัลการกวาดล้างสามดาวและรางวัลการกวาดล้างครั้งที่ 1 ใน Nightmare จะทำให้คุณได้รับรางวัลที่เกี่ยวข้องจาก Reverie",
  str_help_season1_disc_203 = "ไปที่รายละเอียดด่านเพื่อดูข้อมูล Omen ทั้งหมดที่เกี่ยวข้องกับ Awakening in the Storm ซึ่งคุณสามารถสลับไปมาระหว่าง Reverie และ Nightmare",
  str_help_season1_disc_204 = "อีฟรักษารายละเอียดและความชัดเจนในการตัดสินใจ ทำให้เธอสามารถต่อสู้กับ Omen ใน Awakening in the Storm ได้ คะแนนปัญญาจะเติมเต็ม 3 คะแนนทุกวันเวลา 05:00 (UTC+0), 00:00 (UTC-5)",
  str_help_season1_disc_205 = "\"รอยยิ้มนำไปสู่ความสุข\" สามารถให้บัฟที่มีประสิทธิภาพกับอีฟ\nชนะ \"โอเมน\" ใต้ความยากของ \"ฝันร้าย\" เพื่อรับ \"แรงกระแทกของความสุข\" ไอเท็มนี้สามารถเพิ่มระดับของ \"รอยยิ้มนำไปสู่ความสุข\"",
  str_help_season1_disc_206 = "สมบัติลึกลับถูกซ่อนอยู่ใน Cognova และ Nostalix คุณสามารถใส่ไว้ใน Eve's Collection Box อย่าพลาดโอกาสที่จะเปิดมัน",
  str_help_season1_disc_207 = "พายุทรายขวางเส้นทางของอีฟและทำให้หัวใจเธอขุ่นมัว กำจัด Omen รอบตัวคุณเพื่อปัดเป่า Sandstorm!",
  str_help_season1_disc_208 = "อีฟ ที่เสมอภักดี ไม่เคยมีความปรารถนาที่จะทะลุมายากลับ แต่สิ่งที่เธอเอ็นดูนั้นในที่สุดก็ทำให้มันแตกสลาย \"ขอให้ฉันสืบทอดอาวุธของพี่ชาย!\"",
  str_help_season1_disc_209 = "โอ้โห, ฝูง Dream Devourers กำลังกัดกินฝันของอีฟ! ถ้าฝันของเธอพังทลายลง อีฟน่าสงสารอาจจะไม่ตื่นขึ้นมาอีกเลย... เราต้องไม่ปล่อยให้มันเกิดขึ้น!\nตั้งแต่เวลา 05:00 วันที่ 6 กันยายน ถึง 04:00 วันที่ 27 กันยายน, ฝูง Dream Devourers ใหม่จะปรากฏตัวที่ 05:00 ทุกวัน คุณจะมีโอกาสขับไล่พวกมันออกไป 5 ครั้งต่อวัน โดย 2 ครั้งแรกที่ขับไล่สำเร็จจะได้รับรางวัลอย่างอุดมสมบูรณ์ ความยากในการขับไล่ Dream Devourers เหล่านี้จะเพิ่มขึ้นในแต่ละครั้งจนถึงการตั้งค่าใหม่เวลา 05:00 ในวันถัดไป",
  str_help_season1_disc_301 = "เวิร์กชอปแห่งความทรงจำจะมอบรางวัลให้มากมาย ซึ่งหนึ่งในนั้นก็คือชุดคอสตูมกาลครั้งหนึ่งในฤดูใบไม้ผลิ",
  str_help_season1_disc_302 = "แก้ไขโชคลางในฝันเพื่อรับ Metamorpha และชิ้นส่วนของเศษตะกอน",
  str_help_season1_disc_303 = "Metamorpha สามารถนำไปแลกชุด Once Upon a Springtime และ Sediment Shards สามารถนำไปแลกของรางวัลต่าง ๆ อื่น ๆ ได้",
  str_help_season1_disc_304 = "เมื่อ Memory Workshop ปิดลง, Metamorpha จะถูกแปลงเป็น Dream Shards ในอัตราส่วน 1:1 ในขณะที่ Sediment Shards จะถูกแลกเปลี่ยนเป็น Nightium ในอัตราส่วน 1:30 ไอเทมที่เกี่ยวข้องจะถูกส่งตรงไปยังคลังของคุณหลังจากการแปลงสำเร็จ",
