  str_help_season1_disc_403 = "เมื่อปลดล็อกชิ้นส่วนต่างๆ แล้ว คุณยังสามารถค้นพบเรื่องราวที่ซ่อนอยู่เกี่ยวกับอีฟได้อีกด้วย",
