  str_help_season2_disc_101 = "ความเงียบ ความเงียบ! การพิจารณาคดีในหมู่ริมน้ำทองกำลังเริ่มขึ้น!",
  str_help_season2_disc_102 = "แนะนำอิริดอนในการใช้คะแนนปัญญาของเธอเพื่อชนะเส้นขอบในฝัน หลังจากที่เสร็จสิ้น คุณจะสามารถเข้าถึง Counterweights of Soul และ Candle of Justice ซึ่งสามารถนำไปแลกเปลี่ยนเป็นรางวัลหลากหลายในการประมูลที่ตัวอย่างการพิจารณา รวมถึงชุดเสื้อผ้า Fiat Iustitia",
  str_help_season2_disc_103 = "เสร็จสิ้นภารกิจในรายการตรวจสอบเพื่อรับลูมแอมเบอร์เป็นรางวัล",
  str_help_season2_disc_104 = "ทำภารกิจในโลกแห่งความฝันให้สำเร็จเพื่อรับชุด Stand By Me",
  str_help_season2_disc_105 = "หลักฐานทั้งหมดที่รวบรวมได้ในฝันถูกจัดหมวดหมู่และเก็บเอาไว้โดยอิริดอนที่นี่อย่างระเบียบเรียบร้อย",
  str_help_season2_disc_201 = "การทดสอบในระหว่างลอนลานทองเริ่มขึ้นแล้ว แต่ Edge กำลังขัดขวางการตื่นของอิริดอน ช่วยอิริดอนในการจัดการกับ Edge และคุณจะได้รับรางวัลอย่างใจความสำหรับความสำเร็จ โปรดทราบว่าการท้าทายต่อ Edge แต่ละครั้งจะใช้ 1 แต้ม Wit",
  str_help_season2_disc_202 = "มีระดับความยากสองระดับสำหรับการท้าทาย Edge: Reverie และ Nightmare\nในขณะที่ Nightmare นำเสนอประสบการณ์ที่ท้าทายมากขึ้น มันยังให้รางวัลที่ดีกว่าด้วย หากคุณพบว่า Nightmare ยากเกินไป ลองพิจารณาเล่น Reverie ก่อน\nภายในการท้าทาย Edge เดียวกัน ระดับดาวที่ได้รับใน Nightmare จะถูกประสานกันกับ Reverie การสำเร็จในการเคลียร์ดาวสามและรางวัลเคลียร์ครั้งแรกใน Nightmare จะให้รางวัลที่สอดคล้องกันจาก Reverie ด้วย",
  str_help_season2_disc_203 = "เข้าดูรายละเอียดด่านเพื่อดูข้อมูลขอบเขตทั้งหมดที่เกี่ยวข้องกับ \"การทดสอบในคลื่นทอง\" ที่คุณสามารถสลับระหว่างฝันสวรรค์และฝันร้ายได้",
  str_help_season2_disc_204 = "ความสำคัญในการรักษาระดับความเป็นรอบคอบและความชัดเจน ทำให้เธอสามารถท้าทายด่าน Edge ในการทดสอบในระหว่างคลื่นทองคำ คะแนนปัญญาจะเติมเต็ม 3 แต้มทุกวันเวลา 05:00 (UTC+0), 00:00 (UTC-5)",
  str_help_season2_disc_205 = "โฟกัสความจริงสามารถให้ความช่วยเหลือที่แข็งแกร่งในทางข้างหน้า\nเอาชนะ Edge ภายใต้ความยากของ Nightmares เพื่อรับ Light of Justice ไอเท็มนี้สามารถเพิ่มระดับของโฟกัสความจริง",
  str_help_season2_disc_206 = "มีเคล็ดลับลึกลับและหลักฐานทางกายภาพใน Cognova และ Case Files ซึ่งหลังจากได้รับแล้วจะถูกจัดเรียงใน Case Exhibit",
  str_help_season2_disc_207 = "หมอกลึกลับปิดกั้นทางของอิริดอนและคลุมหัวใจของเธอ ต้องเอาชนะเอดจ์รอบ ๆ คุณเพื่อขจัดหมอกลึกลับ!",
  str_help_season2_disc_208 = "รวบรวมเบาะแสและใช้ตราชูแห่งการพิพากษาในการลดลงเพื่อแก้ปัญหาคดีที่พบ!",
  str_help_season2_disc_209 = "โอ้ไม่! ฝูง Dream Devourers กำลังกัดกินฝันของอิริดอน! ถ้าฝันของเธอพังทลาย อิริดอนน่าจะไม่ตื่นขึ้นมาอีกเลย... เราต้องไม่ปล่อยให้มันเกิดขึ้น!\nฝูง Dream Devourers ใหม่จะปรากฏตัวที่ 05:00 ทุกวัน คุณจะมีโอกาส 5 ครั้งในการขับไล่พวกมันทุกวัน โดย 2 ครั้งแรกที่ขับไล่สำเร็จจะได้รับรางวัลอย่างอุดมสมบูรณ์ ความยากในการขับไล่ Dream Devourers นี้จะเพิ่มขึ้นในแต่ละครั้งจนถึงการตั้งค่าใหม่ที่ 05:00 ในวันถัดไป",
  str_help_season2_disc_301 = "การประมูลทดลองนำเสนอรางวัลหลากหลาย ซึ่งในนั้นมีชุด Fiat Iustitia ด้วย",
  str_help_season2_disc_302 = "แก้ปัญหาขอบในฝันเพื่อรับ Counterweights ของวิญญาณและเทียนแห่งความยุติธรรม",
