  str_help_season4_disc_105 = "ทุกอย่างที่เก็บรวบรวมได้ในฝัน ทั้งหมดถูกจัดหมวดหมู่และเก็บรักษาไว้ที่นี่โดยอาเรียอย่างระบบเท่านั้น",
  str_help_season4_disc_201 = "ตำนานของนักดาบได้เริ่มต้นขึ้นแล้ว แต่ Miasma กำลังขัดขวางการก้าวหน้าของอาเรีย ช่วยอาเรียในการกำจัด Miasma และรับรางวัลอย่างหรูหราเมื่อคุณประสบความสำเร็จ โปรดทราบว่าการท้าทายต่อ Miasma ทุกครั้งจะใช้จุด Wit 1 จุด",
  str_help_season4_disc_202 = "มีระดับความยากสองระดับสำหรับการท้าทาย Miasma: Reverie และ Nightmare\nในขณะที่ Nightmare นำเสนอประสบการณ์ที่ท้าทายมากขึ้น มันยังให้รางวัลที่ดีกว่า หากคุณพบว่า Nightmare ยากเกินไป ลองพิจารณาที่จะลอง Reverie ก่อน\nภายในการท้าทาย Miasma เดียวกัน ระดับดาวที่ได้รับใน Nightmare จะถูกประสานกับ Reverie การทำให้ได้รางวัลการเคลียร์ดาวสามและรางวัลการเคลียร์ครั้งแรกใน Nightmare จะยังให้คุณได้รับรางวัลที่สอดคล้องกับ Reverie",
  str_help_season4_disc_203 = "เข้าชมรายละเอียดด่านเพื่อดูข้อมูล Miasma ทั้งหมดที่เกี่ยวข้องกับ Sword Song Under a Canopy of Dreams ที่คุณสามารถสลับระหว่าง Reverie และ Nightmare ได้",
  str_help_season4_disc_204 = "ความชัดเจนและความมีเหตุผลที่เธอสามารถท้าทาย Miasma ใน Sword Song Under a Canopy of Dreams นั้นมาจากคะแนนปัญญา ซึ่งจะเติมเต็มขึ้นทุกวัน 3 คะแนน เวลา 05:00 (UTC+0), 00:00 (UTC-5).",
  str_help_season4_disc_205 = "ดาบฮาร์ทสามารถให้ความช่วยเหลือที่แข็งแกร่งในทางที่คุณเดิน\nชนะในความสยองขวัญของ Miasma เพื่อรับ Sword-Forging Will รายการนี้สามารถเพิ่มระดับของดาบฮาร์ท",
  str_help_season4_disc_206 = "ของเก่าถูกเก็บไว้ในโลง",
  str_help_season4_disc_207 = "Stratus บล็อกทางของอาเรีย จงทำลาย Miasma ที่อยู่รอบ ๆ คุณเพื่อขจัด Stratus!",
  str_help_season4_disc_208 = "โอ้ไม่, ฝูง Dream Devourers กำลังกัดกินฝันของ Areia! ถ้าฝันของเธอพังทลาย สรวง Irridon อาจจะไม่ตื่นขึ้นมาอีกเลย... เราไม่สามารถปล่อยให้มันเกิดขึ้นได้!\nฝูง Dream Devourers ใหม่จะปรากฏขึ้นทุกวันเวลา 05:00 คุณจะมีโอกาสไล่พวกมันออกไป 5 ครั้งทุกวัน โดยการไล่ออกสำเร็จ 2 ครั้งแรกจะได้รับรางวัลอย่างอุดมสมบูรณ์ ความยากในการไล่ Dream Devourers จะเพิ่มขึ้นทุกครั้งที่พยายามจนถึงการรีเซ็ตเวลา 05:00 ในวันถัดไป",
  str_help_season4_disc_301 = "การแลกเปลี่ยนสีเขียวให้คุณเลือกรางวัลหลากหลาย ซึ่งในนั้นมีชุด \"Lavender Splendor\" ด้วย",
  str_help_season4_disc_302 = "แก้ไขมิอัสม่าในฝันเพื่อรับวิสเทอริอาแฮร์ปินและเหรียญทองแดงโบราณ",
  str_help_season4_disc_303 = "พวงผมวิสเทอริอาสามารถแลกเปลี่ยนเป็นชุด Lavender Splendor และเหรียญทองแดงโบราณสามารถแลกเปลี่ยนเป็นรางวัลต่าง ๆ อื่น ๆ",
  str_help_season4_disc_304 = "เมื่อ Verdant Exchange ปิดลง ตรงหมวกผมวิสเทอริอาจะถูกแปลงเป็น Dream Shards ในอัตราส่วน 1:1 ในขณะที่เหรียญทองแดงโบราณจะถูกแลกเปลี่ยนเป็น Nightium ในอัตราส่วน 1:30 สิ่งของที่เกี่ยวข้องจะถูกส่งตรงถึงคุณผ่านทางจดหมาย",
  str_help_season4_disc_305 = "หลังจากที่การแลกเปลี่ยน Verdant ปิดลงแล้ว ชุด Lavender Splendor ยังคงมีจำหน่ายใน Authentic Dreamscapes ในเวลานั้น คุณสามารถแลก Dream Shards ที่แปลงมาจาก Wisteria Hairpins เพื่อรับชุดนี้",
  str_help_season4_disc_401 = "ทำภารกิจใน Missions เพื่อรับลูมแอมเบอร์และรางวัลอื่นๆ",
  str_help_season4_disc_402 = "ทำเควสต์ที่สอดคล้องเพื่อรับลูมแอมเบอร์และรางวัลอื่นๆ",
  str_help_season4_disc_501 = "ทุกอย่างที่เก็บรวบรวมได้ในฝัน ทั้งหมดถูกจัดหมวดหมู่และเก็บรักษาไว้ที่นี่อย่างระบบ โดยอาเรีย",
  str_help_season4_disc_502 = "บันทึกลายพรางความทรงจำเอกสารเหตุการณ์น่าสนใจที่เกิดขึ้นในฝัน และคำใบ้ในการเข้าถึงเนื้อหาที่ยังไม่ได้รวบรวม",
  str_help_season4_disc_503 = "Sonic Memory จับฉวนของเมโลดี้ที่ได้ยินในฝัน",
  str_help_season4_disc_601 = "กิลด์ใหม่ล่าสุดของ Twin Pavilions Bay คือ Indigo Guild ได้เช่าท่าเรือหลายแห่งในพื้นที่ท่าเรือเพื่อเตรียมเข้าร่วมการค้าทางทะเล และดูเหมือนว่าผู้นำของกิลด์นี้จะเป็นท่านหญิงที่ลึกลับและช่างฝีมือจากฝั่งตะวันออก มีการเข้าร่วมกิจกรรมการส่งสินค้าเพื่อสร้างทุนทำงานมากมาย! พลังงานที่ดีที่ได้รับขณะที่คุณสะสมทรัพย์สมบัติของคุณจะช่วยปรับปรุงโชคของคุณและให้ความช่วยเหลือมากมายในการต่อสู้ของคุณในเวลากลางคืน",
  str_help_season4_disc_602 = "เงินทุนหมุนเวียนสามารถใช้ในการอัปเกรดท่าเรือและเรือที่กิลด์เช่า หลังจากที่ถูกอัปเกรดแล้ว ท่าเรือจะมีพนักงานที่มีความสามารถมากขึ้นและความเร็วในการถ่ายโอนสินค้าที่เร็วขึ้น เรือขนาดใหญ่ยิ่งขึ้นสามารถบรรทุกสินค้าได้มากขึ้นและทำกำไรมากขึ้น แต่จะต้องมีพนักงานที่มีความสามารถมากขึ้นเพื่อจัดการทุกอย่างให้ราบรื่น!",
  str_help_season4_disc_603 = "เงินทุนทำงานที่คุณได้รับสามารถใช้ในการจ้างสมาชิกลูกเรือสำหรับเรือของคุณ และสมาชิกลูกเรือแต่ละคนมีคะแนนความสามารถที่แตกต่างกัน อัปเกรดท่าเรือเพื่อจ้างสมาชิกลูกเรือที่มีคะแนนความสามารถสูงขึ้นมากขึ้น",
  str_help_season4_disc_604 = "ลูกเรือที่คุณจ้างมาสามารถถูกมอบหมายให้ทำงานบนเรือใดก็ได้ แต่ลูกเรือแต่ละคนสามารถทำงานบนเรือได้เพียงหนึ่งลำเรือในครั้งเดียว",
  str_help_season4_disc_605 = "สถานะเรือจะมีผลต่อกำไรที่ได้จากการเดินทางแต่ละครั้ง หากสถานะเรืออยู่ที่ 100% คุณจะได้รับเงินทุนการทำงานเท่ากับภาระที่เหลือ สถานะเรือจะถูกกำหนดโดยการส่งมอบ ความสามารถในการขนส่ง และความพร้อม หากมีอย่างใดอย่างหนึ่งไม่ตรงตามข้อกำหนด สถานะเรือจะลดลงอย่างมาก การแต่งตั้งสมาชิกลูกเรือที่เหมาะสมและการตอบสนองต่อเหตุการณ์ในการเดินทางอย่างฉลาดจะเพิ่มกำไรจากการเดินทางของคุณ!",
  str_help_season4_disc_606 = "เหตุการณ์อากาศจะเกิดขึ้นแบบสุ่มที่ท่าเรือและจะรีเฟรชหลังจากการเดินทางทางทะเลจำนวนหนึ่ง ระหว่างการเดินทาง เรือจะเผชิญกับเหตุการณ์การเดินทางทางทะเลที่สุ่มตามเหตุการณ์อากาศ ดังนั้น โปรดทราบสภาพอากาศก่อนการออกเดินทางที่ท่าเรือ!",
  str_help_season4_disc_607 = "เรือจะเผชิญกับเหตุการณ์การเดินเรือสามรายการในแต่ละการเดินทาง และผู้นำทางจะต้องตัดสินใจเกี่ยวกับเหตุการณ์การเดินเรือสามรายการ การกระทำที่เลือกจะส่งผลต่อกำไรที่ได้จากการเดินทางโดยตรง ดังนั้นให้เลือกอย่างระมัดระวัง! หลังจากการเดินทางเสร็จสิ้น เรือจะต้องใช้เวลาในการถ่ายโหลดสินค้า แต่ละเรือมีเวลาถ่ายโหลดของตนเอง ดังนั้นให้วางแผนการเดินเรืออย่างมีเหตุผล",
  str_help_season4_disc_608 = "ในระหว่างการเดินทาง ผู้นำทางสามารถทำรายได้จากเงินทุนการทำงาน ซึ่งสามารถใช้เพื่อจ้างสมาชิกลูกเรือ อัปเกรดท่าเรือ และอัปเกรดเรือ ระดับความเจริญรุ่งเรืองของกิลด์จะเพิ่มขึ้นตามจำนวนเงินทุนการทำงานที่ได้รับ อย่าลืมที่จะพยายามเพื่อรับคะแนนที่สูงขึ้นเพื่อรับรางวัลคะแนน!",
  str_help_season4_disc_609 = "พบกับเป้าหมายเงินทุนหมุนเวียนเพื่ออัปเกรดระดับความเจริญรุ่งเรืองของกิลด์และรับรางวัลพลังงานมงคลทุกครั้งที่อัปเกรด รางวัลพลังงานมงคลสามารถใช้เปิดใช้งานและอัปเกรดความชำนาญในฟงชุยในการเล่นเกม Purging Evil in the Still Night เพื่อทำให้การต่อสู้ง่ายขึ้น!",
  str_help_season4_disc_701 = "ในฐานะพ่อค้าในช่วงกลางวันและนักดาบในช่วงค่ำคืน ในการสืบสวนของขโมยที่ถูกลักลอบและกลไกการลักลอบ ช่างฝีมือและนักดาบต้องเผชิญหน้ากับอุปสรรคมากมายและต้องต่อสู้กับศัตรูโดยตรง! การขับไล่ความชั่วในคืนที่สงบประกอบด้วยห้ากลุ่มของด่านท้าทายแบบเชื่อมต่อกัน และแต่ละกลุ่มของด่านจะถูกปล่อยออกมาทีละน้อยๆตามเวลา!",
  str_help_season4_disc_702 = "ภายใต้ความมืด, ทีมของผู้นำทางไม่จำเป็นต้องเคลื่อนที่ตามช่องสีเดียวกันอีกต่อไป แทนที่จะใช้แรงจุดในการเคลื่อนที่ ทีมจะได้รับคืนจำนวนแรงจุดบางส่วนในตอนแรกของแต่ละรอบ และผู้เล่นสามารถเลือกกลยุทธ์การต่อสู้ที่เหมาะสมตามจำนวนแรงจุดที่พวกเขามี เพื่อเลือกเส้นทางที่ดีที่สุดและทำลายศัตรูได้มากขึ้น!",
  str_help_season4_disc_703 = "ผู้นำทางสามารถใช้พลังงานมงคลที่ได้รับจากการเล่นเกมพ่อค้ากลางวันในการอัปเกรดอาร์เรย์ฮวงจุ้ยห้าธาตุ ซึ่งจะปลดล็อคโหนดและความชำนาญการจัดรูปแบบฮวงจุ้ยที่มีอำนาจต่างๆ โหนดการจัดรูปแบบเป็นส่วนสำคัญของอาร์เรย์ฮวงจุ้ยและต้องถูกเปิดใช้งานเพื่อใช้ความชำนาญที่อยู่ภายใน พลังงานมงคลที่ใช้มากขึ้น โหนดการจัดรูปแบบและความชำนาญที่สามารถเปิดใช้งานได้ก็จะมากขึ้น.",
  str_help_season4_disc_704 = "นอกจากการเปิดใช้งานโหนดรูปแบบแล้ว ทักษะฟงชุยทั้งหมดสามารถติดตั้งเพื่อให้มีผลในด่านและช่วยผู้นำทางในการต่อสู้ จำนวนทักษะที่สามารถติดตั้งได้จะเพิ่มขึ้นอย่างทีละครั้งเมื่อมีการเปิดใช้งานและอัปเกรดโหนดรูปแบบมากขึ้น สูงสุด 4 ทักษะในด่าน โปรดเลือกการผสมผสานทักษะที่ดีที่สุดสำหรับทีมของคุณ!",
  str_help_season4_disc_705 = "พบกับเป้าหมายเงินทุนหมุนเวียนในการเล่นของพ่อค้ากลางวันเพื่ออัปเกรดระดับความเจริญรุ่งเรืองของกิลด์และรับรางวัลพลังงานมงคล พลังงานมงคลสามารถใช้เปิดใช้งานและอัปเกรดความชำนาญในฟงชุยในการเล่นเกมการขับไล่ความชั่วในคืนที่เงียบสงบเพื่อทำให้การต่อสู้ง่ายขึ้น!",
